  "Toughness": "Dureza", "+1 physical DR on every location.": "+1 RD física en todas las localizaciones.",

  // quirk lines tied to the first perk
  "Punches first, asks questions never.": "Primero pega, y nunca pregunta.",
  "Collects knife-sharpening stones like trophies.": "Colecciona piedras de afilar como si fueran trofeos.",
  "Learned a 'secret technique' from a pre-war holotape.": "Aprendió una «técnica secreta» de una holocinta de antes de la guerra.",
  "Fights end fast and messy when they're around.": "Cuando anda cerca, las peleas acaban rápido y mal.",
  "Gets scarier the more they bleed.": "Da más miedo cuanto más sangra.",
  "Still practicing for a baseball season that ended in 2077.": "Sigue entrenando para una temporada de béisbol que acabó en 2077.",
  "Thinks the stock of a rifle is the business end.": "Cree que la culata del rifle es la parte que dispara.",
  "Announces every charge with a train whistle. Choo choo.": "Anuncia cada embestida con un silbato de tren. Chu, chu.",
  "Has walked off falls that should've been fatal.": "Se ha levantado de caídas que deberían haber sido mortales.",
  "Hands are a blur whenever someone says 'draw'.": "Sus manos se vuelven un borrón en cuanto alguien dice «desenfunda».",
  "Aims for the chest because 'it's the big bit'.": "Apunta al pecho porque «es la parte grande».",
  "Fans the hammer like a pre-war movie cowboy.": "Abanica el percutor como un vaquero de película de antes de la guerra.",
  "Breathes out slowly before every single shot.": "Suelta el aire despacio antes de cada disparo.",
  "Fires at two targets at once and calls it style.": "Dispara a dos objetivos a la vez y lo llama estilo.",
  "Never stands still in a fight. Or in a conversation.": "Nunca se está quieto en una pelea. Ni en una conversación.",
  "Can name the exact rib they plan to hit.": "Puede decirte qué costilla exacta piensa alcanzar.",
  "Studies people the way others study maps.": "Estudia a la gente como otros estudian mapas.",
  "Keeps firing at the same spot until something gives.": "Sigue disparando al mismo punto hasta que algo cede.",
  "Sleeps all day, prowls all night.": "Duerme todo el día y merodea toda la noche.",
  "Has an answer for everything, usually a good one.": "Tiene respuesta para todo, y suele ser buena.",
  "Lies so smoothly they sometimes believe it themselves.": "Miente tan bien que a veces se lo cree.",
  "Haggles over every single cap, on principle.": "Regatea cada chapa, por principios.",
  "Leaves a trail of broken hearts across the wastes.": "Deja un reguero de corazones rotos por todo el Yermo.",
  "Gives rousing speeches at the worst possible moments.": "Suelta discursos inspiradores en el peor momento posible.",
  "Could sell sand to a Mojave raider.": "Podría venderle arena a un saqueador del Mojave.",
  "Never goes anywhere without a very good dog.": "Nunca va a ningún sitio sin un perro muy bueno.",
  "Wild animals tend to just... like them.": "Los animales salvajes, simplemente... le cogen cariño.",
  "Bolts scrap metal onto everyone's coats, asked or not.": "Atornilla chatarra a los abrigos de todo el mundo, se lo pidan o no.",
  "Can't walk past a terminal without 'having a look'.": "No puede pasar junto a un terminal sin «echar un vistazo».",
  "Holds the world together with duct tape and hope.": "Mantiene el mundo en pie con cinta adhesiva y esperanza.",
  "Reads every magazine twice and quotes it constantly.": "Lee cada revista dos veces y la cita sin parar.",
  "Hums happily whenever the Geiger counter clicks.": "Tararea feliz cada vez que el contador Geiger chasquea.",
  "Brews mystery chems in an old cooking pot.": "Prepara drogas misteriosas en una vieja olla.",
  "Patches people up whether they want it or not.": "Cura a la gente, quiera o no.",
  "Always has a bandage and a lecture ready.": "Siempre tiene a mano una venda y un sermón.",
  "Wounds close up suspiciously fast.": "Sus heridas se cierran sospechosamente rápido.",
  "Is always hungry, and always healing.": "Siempre tiene hambre, y siempre se está curando.",
  "You won't hear them coming. Nobody ever does.": "No lo oirás llegar. Nadie lo oye nunca.",
  "Treats every locked door as a personal insult.": "Se toma cada puerta cerrada como un insulto personal.",
  "Hums a lullaby before every silent takedown.": "Tararea una nana antes de cada eliminación silenciosa.",
  "Moves like a cat around pressure plates.": "Se mueve como un gato entre placas de presión.",
  "Disappears into shadows mid-sentence.": "Desaparece entre las sombras a mitad de frase.",
  "Your caps are already in their pocket.": "Tus chapas ya están en su bolsillo.",
  "Shakes hands and walks off with your watch.": "Te da la mano y se va con tu reloj.",
  "Wears trophies from every mutant beast they've bagged.": "Lleva trofeos de cada bestia mutante que ha cazado.",
  "Knows a shortcut everywhere. Some of them even work.": "Conoce un atajo para todo. Algunos hasta funcionan.",
  "Drinks straight from irradiated puddles.": "Bebe directamente de charcos irradiados.",
  "Happier underwater than on land.": "Es más feliz bajo el agua que en tierra.",
  "Has been bitten by everything and shrugged it off.": "Le ha mordido de todo y ni se ha inmutado.",
  "Glows a little, but in a healthy way.": "Brilla un poco, pero de forma saludable.",
  "Names every bloatfly before killing it.": "Le pone nombre a cada hinchamosca antes de matarla.",
  "Sunbathes at noon to 'recharge'.": "Toma el sol a mediodía para «recargarse».",
  "Signs their work with a scorch mark.": "Firma su trabajo con una marca de quemadura.",
  "Throws grenades like a pre-war quarterback.": "Lanza granadas como un quarterback de antes de la guerra.",
  "Things tend to explode messily around them.": "Las cosas suelen explotar de forma muy sucia a su alrededor.",
  "Takes every bet, especially the stupid ones.": "Acepta todas las apuestas, sobre todo las estúpidas.",
  "Checks every corner twice. Then once more.": "Revisa cada esquina dos veces. Y luego otra más.",
  "A man in a trench coat seems to follow them around.": "Un hombre con gabardina parece seguirle a todas partes.",
  "Somehow always hits right where it hurts.": "De algún modo siempre da justo donde duele.",
  "Finds canned food in places no one else looks.": "Encuentra latas de comida donde nadie más mira.",
  "Pockets jingle with spare ammo at all times.": "Sus bolsillos tintinean siempre con munición de sobra.",
  "Gets a burst of energy after every kill.": "Recibe un chute de energía después de cada muerte.",
  "Medicine cabinets just seem to open up for them.": "Los botiquines parecen abrirse solos para él.",
  "Skin like old saddle leather.": "Tiene la piel como el cuero de una silla de montar vieja.",
  "Believes every problem can be solved with a bigger gun.": "Cree que todo problema se resuelve con un arma más grande.",
  "Carries everyone's loot. Charges for it.": "Carga con el botín de todos. Y cobra por ello.",
  "Has tried every chem in the wasteland and kicked them all.": "Ha probado todas las drogas del Yermo y las ha dejado todas.",
  "Laser beams seem to bend away from them.": "Los rayos láser parecen desviarse a su paso.",
  "Leaves glowing piles where enemies used to be.": "Deja montones brillantes donde antes había enemigos.",
  "Always has energy for one more move.": "Siempre le queda energía para un movimiento más.",
  "Closes distance before you can blink.": "Acorta distancias antes de que parpadees.",
  "Makes every hit count, with flair.": "Hace que cada golpe cuente, y con estilo.",
  "Brings the party, and the bottles.": "Trae la fiesta, y las botellas.",
  "Calls a shotgun blast 'outpatient surgery'.": "Llama a un escopetazo «cirugía ambulatoria».",

