  "Re-roll 1d20 on all INT tests while armor is powered": "Repite 1d20 en todas las pruebas de INT mientras la armadura tenga energía",
  "Re-roll 1d20 on all PER and AGI tests, +2 DC to sneak attack damage": "Repite 1d20 en todas las pruebas de PER y AGI, +2 DC al daño de los ataques furtivos",
  "Re-roll 1d20 on all PER tests while armor is powered": "Repite 1d20 en todas las pruebas de PER mientras la armadura tenga energía",
  "Re-roll 1d20 on all PER tests, May attempt PER tests to detect things which cannot normally be detected by the naked eye, such as radiation": "Repite 1d20 en todas las pruebas de PER. Permite pruebas de PER para detectar lo que no se ve a simple vista, como la radiación",
  "Re-roll 1d20 on all STR and END tests, +3 Max HP": "Repite 1d20 en todas las pruebas de FUE y RES, +3 PV máx.",
  "Re-roll addiction roll for addictive chems while armor is powered": "Repite la tirada de adicción a drogas mientras la armadura tenga energía",
