  "Recon Scope": "Mira de reconocimiento",
  "Recon Sensors": "Sensores de reconocimiento",
  "Reduce difficulty of all STR tests by 1 and increase difficulty of all INT tests by 2 (in total)": "-1 a la dificultad de todas las pruebas de FUE y +2 a la de todas las de INT (en total)",
  "Reduce difficulty of tests to detect hidden opponents by 1 (min. 0), Enemies visible to you who attempt to hide add +1 to the difficulty of their Sneak tests": "Reduce en 1 la dificultad de las pruebas para detectar enemigos ocultos (mín. 0). Los enemigos que te ven y tratan de esconderse suman +1 a la dificultad de su prueba de Sigilo",
  "Reduce the difficulty of CHA and LCK tests by 1 (minimum 0), +1 difficulty to STR tests": "-1 a la dificultad de las pruebas de CAR y SUE (mínimo 0), +1 a la dificultad de las pruebas de FUE",
  "Reduce the difficulty of CHA tests by 2, to a minimum of 0, Re-roll 1d20 on Barter tests": "-2 a la dificultad de las pruebas de CAR (mínimo 0), repite 1d20 en las pruebas de Trueque",
  "Reduce the difficulty of INT tests by 2 (minimum 0)": "-2 a la dificultad de las pruebas de INT (mínimo 0)",
  "Reduce the difficulty of Lockpick tests by 1 (min. 0), Does not need bobby pins or other lockpicking tools": "Reduce en 1 la dificultad de las pruebas de Forzar cerraduras (mín. 0). No necesita horquillas ni otras herramientas",
  "Reduce the difficulty of Medicine tests by 1 (min. 0)": "Reduce en 1 la dificultad de las pruebas de Medicina (mín. 0)",
  "Reduce the difficulty of Medicine tests by 1 (minimum 0), When providing long-term care, allows care of up to 2 additional patients": "Reduce en 1 la dificultad de las pruebas de Medicina (mínimo 0). En cuidados prolongados, permite atender hasta a 2 pacientes más",
  "Reduce the difficulty of PER tests by 2 (min. 0), Aim minor action lets you re-roll one additional d20": "-2 a la dificultad de las pruebas de PER (mín. 0); la acción menor Apuntar te deja repetir un d20 más",
  "Reduce the difficulty of Repair tests by 1 (minimum 0)": "Reduce en 1 la dificultad de las pruebas de Reparación (mínimo 0)",
  "Reduce the difficulty of Repair tests by 1 (minimum 0), May attempt Repair tests which normally require a workbench or similar at +1 difficulty": "Reduce en 1 la dificultad de las pruebas de Reparación (mínimo 0). Permite pruebas de Reparación que normalmente piden un banco de trabajo, con +1 a la dificultad",
  "Reduce the difficulty of Speech tests by 1 (min. 0)": "Reduce en 1 la dificultad de las pruebas de Conversación (mín. 0)",
  "Reduce the difficulty of Survival tests to detect and disable traps and similar hazards by 1 (min. 0)": "Reduce en 1 la dificultad de las pruebas de Supervivencia para detectar y desactivar trampas y peligros parecidos (mín. 0)",
  "Reduce the difficulty of all END tests by 1 until the end of the next scene": "-1 a la dificultad de todas las pruebas de RES hasta el final de la siguiente escena",
  "Reduce the difficulty of all PER and INT tests by 1 (minimum 0), +1 difficulty to CHA tests": "-1 a la dificultad de todas las pruebas de PER e INT (mínimo 0), +1 a la dificultad de las pruebas de CAR",
  "Reduce the difficulty of all STR and END tests by 1 (minimum 0). +4 Max HP, Gain 3 AP immediately (lost if not spent), Extra actions cost 1 less AP": "-1 a la dificultad de todas las pruebas de FUE y RES (mínimo 0). +4 PV máx., ganas 3 PA al instante (se pierden si no los gastas), las acciones extra cuestan 1 PA menos",
  "Reduce the difficulty of all STR, PER, and END tests by 1 (minimum 0), +4 Max HP": "-1 a la dificultad de todas las pruebas de FUE, PER y RES (mínimo 0), +4 PV máx.",
  "Reduces difficulty of Lockpick tests by 1 (minimum 0), After 3 complications, the set is broken": "Reduce en 1 la dificultad de las pruebas de Forzar cerraduras (mínimo 0). Tras 3 complicaciones, el juego se rompe",
  "Reduces difficulty of Lockpick tests by 1 (minimum 1), One bobby pin breaks per complication rolled": "Reduce en 1 la dificultad de las pruebas de Forzar cerraduras (mínimo 1). Se rompe una horquilla por cada complicación",
  "Reduces difficulty of Lockpick tests by 2 (minimum 0), Ignores first complication rolled, Breaks if two or more complications are rolled at once": "Reduce en 2 la dificultad de las pruebas de Forzar cerraduras (mínimo 0). Ignora la primera complicación. Se rompe si salen dos o más complicaciones a la vez",
  "Reduces the difficulty of Science tests to hack into locked computer systems by 1 (min. 0)": "Reduce en 1 la dificultad de las pruebas de Ciencia para piratear sistemas informáticos bloqueados (mín. 0)",
