// ---- fallout ttrpg perks
Object.assign(ES, {
  "Fallout TTRPG Perks": "Ventajas de Fallout TTRPG",
  "Every perk from the core rulebook that is also a Fallout 76 card": "Ventajas del libro básico que también son cartas de Fallout 76",
  "Perks": "Ventajas",
  "Requirements": "Requisitos",
  "Ranks": "Rangos",
  "Level {n}+": "Nivel {n}+",
  "No requirements": "Sin requisitos",
  "each extra rank needs {n} more levels": "cada rango extra pide {n} niveles más",
  "Not for robots": "No para robots",
  "Not for ghouls": "No para necrófagos",
  "Not for humans": "No para humanos",
  "Not for super mutants": "No para supermutantes",
  "No attribute requirement": "Sin requisito de atributo",
  "Needs {list}": "Necesita {list}",
  "{n} rank": "{n} rango",
  "{n} ranks": "{n} rangos",
  "Rank {r} of {m}": "Rango {r} de {m}",
  "Rank {r} needs level {n}": "El rango {r} necesita nivel {n}",
  "SUGGEST A PERK": "SUGERIR UNA VENTAJA",
  "{lvl}: level {l}, {n} perk taken (one per level)": "{lvl}: nivel {l}, {n} ventaja elegida (una por nivel)",
  "{lvl}: level {l}, {n} perks taken (one per level)": "{lvl}: nivel {l}, {n} ventajas elegidas (una por nivel)",
  "meets {list}": "cumple {list}",
  "Nothing fits {name} right now: the remaining perks need higher S.P.E.C.I.A.L., a higher level or another origin. Level up the character, or loosen the filter.": "Ahora mismo no encaja nada con {name}: las demás ventajas piden más S.P.E.C.I.A.L., más nivel u otro origen. Sube de nivel al personaje o quita el filtro.",
  "It doesn't meet the requirements for {name} right now, but you can still add it.": "Ahora mismo {name} no cumple los requisitos, pero puedes añadirla igualmente.",
  "{name} meets the requirements.": "{name} cumple los requisitos.",
  "Fallout 76 card, not in the rulebook": "Carta de Fallout 76, no está en el libro",
  "Perks (core rulebook)": "Ventajas (libro básico)",
  "Type a perk name to add it": "Escribe el nombre de una ventaja para añadirla",
  "Requirements not met": "No cumple los requisitos",
  "Card art: fallout.wiki": "Imagen de la carta: fallout.wiki",
  "Fallout 2d20 core rulebook": "Libro básico de Fallout 2d20",
  "New perk": "Ventaja nueva",
  "{n} perk": "{n} ventaja",
  "{n} perks": "{n} ventajas",
  "No perks yet. Add them here, or from the Fallout TTRPG Perks page.": "Aún no tiene ventajas. Añádelas aquí o desde la página Ventajas de Fallout TTRPG.",
  "Raise whatever went up this level (S.P.E.C.I.A.L., skill ranks, perk cards, notes), then press <b>Save changes</b>. By the rulebook that's +1 max HP, +1 to one skill rank and one new perk (or one more rank) whose requirements you meet. Use <b>Fallout TTRPG Perks</b> afterwards for a suggestion.": "Sube lo que haya mejorado en este nivel (S.P.E.C.I.A.L., rangos de habilidad, ventajas, notas) y pulsa <b>Guardar cambios</b>. Según el libro, cada nivel da +1 PV máximo, +1 a un rango de habilidad y una ventaja nueva (o un rango más) cuyos requisitos cumplas. Después usa <b>Ventajas de Fallout TTRPG</b> para que te sugiera una.",
  "The perks from the Fallout 2d20 core rulebook (pages 59 to 73) that are also Fallout 76 perk cards, with the rulebook's ranks, requirements and description. Browse them, get a random one, or pick a saved character to get one they can take. The card pictures come from fallout.wiki and need internet.": "Las ventajas del libro básico de Fallout 2d20 (páginas 59 a 73) que también son cartas de ventaja de Fallout 76, con los rangos, requisitos y descripción del libro. Recórrelas, saca una al azar o elige un personaje guardado para que te sugiera una que pueda coger. Las imágenes de las cartas vienen de fallout.wiki y necesitan internet.",
  "Requires S.P.E.C.I.A.L.": "Requiere S.P.E.C.I.A.L.",
  "+ Add perk": "+ Añadir ventaja",
  "No perks yet. Tap <b>Suggest a perk</b> to get one picked for this character.": "Aún no tiene ventajas. Toca <b>Sugerir una ventaja</b> para que se elija una para este personaje.",
  "Every perk from the core rulebook, with its requirements": "Todas las ventajas del libro básico, con sus requisitos",
  "Every perk from the Fallout 2d20 core rulebook (pages 59 to 73), with the rulebook's ranks, requirements and description. Browse them, get a random one, or pick a saved character to get one they can take. The pictures are the Fallout 76 cards from fallout.wiki (they need internet); perks that aren't Fallout 76 cards have no picture yet.": "Todas las ventajas del libro básico de Fallout 2d20 (páginas 59 a 73), con los rangos, requisitos y descripción del libro. Recórrelas, saca una al azar o elige un personaje guardado para que te sugiera una que pueda coger. Las imágenes son las cartas de Fallout 76 de fallout.wiki (necesitan internet); las ventajas que no son cartas de Fallout 76 aún no tienen imagen.",
  "When you spend AP to take an additional major action, you do not suffer the increased skill test difficulty during your second action.": "Cuando gastas PA para hacer una acción principal adicional, no sufres el aumento de dificultad de las pruebas de habilidad durante tu segunda acción.",
  "Action Boy / Girl": "Chico / Chica de acción",
  "When you suffer damage, the amount of damage needed to inflict a critical hit on you increases by your rank in this perk. For example, if you have one rank in this perk, you suffer a critical hit from 6 or more damage, rather than 5 or more.": "Cuando sufres daño, la cantidad de daño necesaria para infligirte un golpe crítico aumenta en tu rango en esta ventaja. Por ejemplo, con un rango sufres un golpe crítico con 6 o más de daño, en lugar de con 5 o más.",
  "When your health is below its maximum value, you count your STR score as 10 for all purposes when attempting a STR-based skill test or melee attack.": "Cuando tu salud está por debajo de su máximo, cuentas tu FUE como 10 a todos los efectos al hacer una prueba de habilidad basada en FUE o un ataque cuerpo a cuerpo.",
  "Adrenalin Rush": "Subidón de adrenalina",
  "At rank 1, whenever a creature NPC with the Mammal, Lizard, or Insect keyword would attack you, roll 1 CD: on any result other than an Effect, the creature chooses not to attack you, although it may still attack another character it can target.": "En el rango 1, cada vez que una criatura PNJ con la palabra clave Mamífero, Lagarto o Insecto vaya a atacarte, tira 1 DC: con cualquier resultado que no sea un Efecto, la criatura decide no atacarte, aunque puede atacar a otro personaje a su alcance.",
  "At rank 2, you can attempt a CHA + Survival test with a difficulty of 2 as a major action. If you succeed, the animal treats you as friendly and will attack anyone who attacks you. Mighty and Legendary animals are unaffected by this perk.": "En el rango 2, puedes intentar una prueba de CAR + Supervivencia con dificultad 2 como acción principal. Si tienes éxito, el animal te trata como amigo y atacará a quien te ataque. Esta ventaja no afecta a los animales Poderosos ni Legendarios.",
  "Water is your ally. At rank 1, you no longer take radiation damage from swimming in irradiated water, and you can hold your breath for twice as long as normal.": "El agua es tu aliada. En el rango 1, ya no recibes daño por radiación al nadar en agua irradiada y puedes aguantar la respiración el doble de lo normal.",
  "At rank 2, enemies add +2 to the difficulty to tests to detect you while you are submerged underwater.": "En el rango 2, los enemigos suman +2 a la dificultad de las pruebas para detectarte mientras estás sumergido bajo el agua.",
  "Aquaboy / Aquagirl": "Chico acuático / Chica acuática",
  "You can modify armor with armor mods. Each rank in this perk unlocks an additional rank of mods: rank 1 unlocks rank 1 mods, rank 2 unlocks rank 2 mods, etc.": "Puedes modificar armaduras con mods de armadura. Cada rango de esta ventaja desbloquea un rango más de mods: el rango 1 desbloquea los mods de rango 1, el rango 2 los de rango 2, etc.",
  "When you take the Aim minor action at a target within Close range, you spot their weaknesses and can attack more efficiently. The next attack you make against that target gains the Piercing 1 damage effect, or improves the rating of any existing Piercing X damage effect by 1.": "Cuando haces la acción secundaria Apuntar contra un objetivo a corto alcance, ves sus puntos débiles y atacas con más eficacia. Tu siguiente ataque contra ese objetivo gana el efecto de daño Perforante 1, o mejora en 1 el valor de un efecto Perforante X que ya tenga.",
  "Your physical Damage Resistance increases on all hit locations based on your STR. You do not gain this benefit while wearing Power Armor.": "Tu resistencia al daño físico aumenta en todas las localizaciones según tu FUE. No obtienes este beneficio si llevas servoarmadura.",
  "STR 7-8: +1 physical DR. STR 9-10: +2. STR 11+: +3.": "FUE 7-8: +1 RD física. FUE 9-10: +2. FUE 11 o más: +3.",
  "Barbarian": "Bárbaro",
  "When you make a melee attack by bashing with your gun (see p.111), your attack gains the Vicious damage effect.": "Cuando haces un ataque cuerpo a cuerpo golpeando con tu arma de fuego (ver p. 111), el ataque gana el efecto de daño Despiadado.",
  "When you inflict one or more points of damage to an enemy, you may spend 1 Luck Point to automatically inflict a critical hit, causing an injury.": "Cuando infliges uno o más puntos de daño a un enemigo, puedes gastar 1 punto de Suerte para infligir automáticamente un golpe crítico, que causa una herida.",
  "When you make a melee attack with a two-handed melee weapon, the weapon gains the Vicious damage effect.": "Cuando haces un ataque cuerpo a cuerpo con un arma cuerpo a cuerpo a dos manos, el arma gana el efecto de daño Despiadado.",
  "The Black Widow perk affects men and masculine characters, while the Lady Killer perk affects women and feminine characters - they are otherwise identical. When you attempt a CHA-based skill test to influence a character of the chosen gender, you may re-roll 1d20. In addition, your attacks inflict +1 CD additional damage against characters of the chosen gender.": "Viuda negra afecta a hombres y personajes masculinos, y Rompecorazones afecta a mujeres y personajes femeninos; por lo demás son idénticas. Cuando haces una prueba de habilidad basada en CAR para influir en un personaje del género elegido, puedes repetir 1d20. Además, tus ataques infligen +1 DC de daño adicional contra personajes del género elegido.",
  "Black Widow / Lady Killer": "Viuda negra / Rompecorazones",
  "You can modify melee weapons with weapon mods. Each rank in this perk unlocks an additional rank of melee weapon mods: rank 1 unlocks rank 1 mods, rank 2 unlocks rank 2 mods, and rank 3 unlocks rank 3 mods.": "Puedes modificar armas cuerpo a cuerpo con mods de arma. Cada rango de esta ventaja desbloquea un rango más de mods de armas cuerpo a cuerpo: el rango 1 desbloquea los mods de rango 1, el rango 2 los de rango 2 y el rango 3 los de rango 3.",
  "When you move into reach of an opponent and make a melee attack against them in one turn, you may re-roll one d20 on your attack.": "Cuando te mueves hasta el alcance de un oponente y le haces un ataque cuerpo a cuerpo en el mismo turno, puedes repetir un d20 de tu ataque.",
  "At rank 2, you also inflict +1 CD damage with that attack.": "En el rango 2, además infliges +1 DC de daño con ese ataque.",
  "When you inflict a critical hit, roll 1 CD; if you roll an Effect, you inflict one additional injury to a random location.": "Cuando infliges un golpe crítico, tira 1 DC; si sale un Efecto, infliges una herida adicional en una localización al azar.",
  "When you are scavenging a location that contains food, you gain 1 additional random food item, without spending AP.": "Cuando rebuscas en un lugar que contiene comida, obtienes 1 alimento aleatorio adicional, sin gastar PA.",
  "When you buy or sell items, you may increase or decrease the price of the goods being traded by 10%.": "Cuando compras o vendes objetos, puedes subir o bajar un 10 % el precio de lo que se intercambia.",
  "Whenever you attempt a skill test, and you buy one or more d20s by spending Action Points, you may re-roll 1d20 on that test. You may not purchase this perk if you have Daring Nature.": "Cada vez que haces una prueba de habilidad y compras uno o más d20 gastando puntos de acción, puedes repetir 1d20 en esa prueba. No puedes coger esta ventaja si tienes Naturaleza osada.",
  "When you make a ranged attack, you may choose to strike your target's Torso location (or equivalent, for creatures that use a different location table) without increasing the difficulty of the attack. In addition, you may re-roll 1d20 when making the test for your attack.": "Cuando haces un ataque a distancia, puedes apuntar al torso del objetivo (o su equivalente, en criaturas con otra tabla de localizaciones) sin aumentar la dificultad del ataque. Además, puedes repetir 1d20 en la prueba del ataque.",
  "At rank 1, roll one fewer CD when determining if you become addicted to chems, to a minimum of 0.": "En el rango 1, tira un DC menos al comprobar si te vuelves adicto a las drogas, hasta un mínimo de 0.",
  "At rank 2, you cannot become addicted to chems.": "En el rango 2, no puedes volverte adicto a las drogas.",
  "Chems you create last twice as long as normal (see p.164). In addition, you unlock chems recipes that have this perk as a requirement.": "Las drogas que fabricas duran el doble de lo normal (ver p. 164). Además, desbloqueas las recetas de drogas que piden esta ventaja.",
  "When you make a ranged attack with any weapon with a Fire Rate of 3 or higher (except heavy weapons), you add +1 CD per rank to the weapon's damage.": "Cuando haces un ataque a distancia con cualquier arma de Cadencia 3 o más (salvo armas pesadas), sumas +1 DC por rango al daño del arma.",
  "Commando": "Comando",
  "After you use the bonus gained from reading a magazine, roll 1 CD. If you roll an Effect, you may use that bonus one additional time.": "Después de usar la bonificación de leer una revista, tira 1 DC. Si sale un Efecto, puedes usar esa bonificación una vez más.",
  "When you make a ranged attack and spend ammunition to increase the damage, you may re-roll up to 3 CD for your damage roll.": "Cuando haces un ataque a distancia y gastas munición para aumentar el daño, puedes repetir hasta 3 DC de tu tirada de daño.",
  "Whenever you attempt a skill test, and you buy one or more d20s by giving the gamemaster Action Points, you may re-roll 1d20 on that test. You may not purchase this perk if you have Cautious Nature.": "Cada vez que haces una prueba de habilidad y compras uno o más d20 dándole puntos de acción al director de juego, puedes repetir 1d20 en esa prueba. No puedes coger esta ventaja si tienes Naturaleza cautelosa.",
  "When you make an attack using a weapon with the Blast quality, the attack gains the Vicious damage effect. In addition, you unlock explosives recipes which have this perk as a requirement.": "Cuando atacas con un arma con la cualidad Explosiva, el ataque gana el efecto de daño Despiadado. Además, desbloqueas las recetas de explosivos que piden esta ventaja.",
  "At rank 1, when you take the Defend major action, you reduce the difficulty of the skill test by 1. At rank 2, the AP cost to further increase your Defense is reduced to 1 AP.": "En el rango 1, cuando haces la acción principal Defender, reduces en 1 la dificultad de la prueba de habilidad. En el rango 2, el coste en PA para aumentar más tu Defensa baja a 1 PA.",
  "Dodger": "Escurridizo",
  "You aren't alone in the wilderness. You have a pet dog that serves as a friend and ally in dangerous times. The dog has the profile shown to the side and is treated as an allied NPC creature under your command (see p.338). If you need to forage for food and water, your dog looks after themselves. If your dog is slain, then you either find a new dog before the next adventure, or you may trade this perk for a different one after this adventure.": "No estás solo en el yermo. Tienes un perro que es tu amigo y aliado en los momentos peligrosos. El perro tiene el perfil que aparece en el libro y cuenta como una criatura PNJ aliada bajo tu mando (ver p. 338). Si necesitas buscar comida y agua, tu perro se las apaña solo. Si tu perro muere, puedes encontrar otro antes de la siguiente aventura, o cambiar esta ventaja por otra al terminar esta aventura.",
  "When you make an attack against an NPC with the Insect keyword, your attack gains the Piercing 1 damage effect, or improves the rating of any Piercing X effect the weapon has by +1.": "Cuando atacas a un PNJ con la palabra clave Insecto, tu ataque gana el efecto de daño Perforante 1, o mejora en +1 el valor de cualquier efecto Perforante X que tenga el arma.",
  "When you regain one or more HP from any source other than rest, increase the total HP regained by +1 per rank in this perk.": "Cuando recuperas uno o más PV por cualquier medio que no sea descansar, el total de PV recuperados aumenta en +1 por rango de esta ventaja.",
  "When you make an END + Survival test to heal your own injuries, the first additional d20 you buy is free. The normal maximum of 5d20 still applies.": "Cuando haces una prueba de RES + Supervivencia para curar tus propias heridas, el primer d20 adicional que compres es gratis. El máximo normal de 5d20 sigue aplicándose.",
  "Once per combat encounter, you may re-roll all the CD on a single damage roll without spending any Luck points.": "Una vez por combate, puedes repetir todos los DC de una tirada de daño sin gastar puntos de Suerte.",
  "Whenever you roll to determine how much money you find, you find more. At rank 1, you find +3 CD additional caps. At rank 2, you find +6 CD additional caps. At rank 3, you find +10 CD additional caps.": "Cada vez que tiras para saber cuánto dinero encuentras, encuentras más. En el rango 1, encuentras +3 DC chapas adicionales. En el rango 2, +6 DC chapas adicionales. En el rango 3, +10 DC chapas adicionales.",
  "Fortune Finder": "Buscafortunas",
  "Whenever you attempt an AGI + Sneak test in shadows or darkness, the first additional d20 you buy is free. The normal maximum of 5d20 still applies.": "Cada vez que haces una prueba de AGI + Sigilo en sombras u oscuridad, el primer d20 adicional que compres es gratis. El máximo normal de 5d20 sigue aplicándose.",
  "When you make an attack which kills one or more enemies, roll 1 CD. If you roll an Effect, add 2 AP to the group's pool.": "Cuando haces un ataque que mata a uno o más enemigos, tira 1 DC. Si sale un Efecto, añade 2 PA a la reserva del grupo.",
  "When you succeed at a ranged attack, you may spend 1 AP and 1 ammo to hit a second target within Close range of your initial target. The second target takes the same damage as the initial target. At rank 2, you may spend 2 AP and 2 ammo to hit two additional targets. At rank 3, you may spend 3 AP and 3 ammo to hit three additional targets.": "Cuando aciertas un ataque a distancia, puedes gastar 1 PA y 1 de munición para alcanzar a un segundo objetivo a corto alcance del primero. El segundo objetivo recibe el mismo daño que el primero. En el rango 2, puedes gastar 2 PA y 2 de munición para alcanzar a dos objetivos más. En el rango 3, puedes gastar 3 PA y 3 de munición para alcanzar a tres objetivos más.",
  "You can modify small guns and heavy weapons with weapon mods. Each rank in this perk unlocks an additional rank of weapon mods: rank 1 unlocks rank 1 mods, rank 2 unlocks rank 2 mods, etc.": "Puedes modificar armas ligeras y armas pesadas con mods de arma. Cada rango de esta ventaja desbloquea un rango más de mods de arma: el rango 1 desbloquea los mods de rango 1, el rango 2 los de rango 2, etc.",
  "When you make an attack with a one-handed ranged weapon with a Fire Rate of 2 or lower, you increase the weapon's damage by +1 CD per rank. In addition, you may re-roll the hit location die.": "Cuando atacas con un arma a distancia a una mano con Cadencia 2 o menos, el daño del arma aumenta en +1 DC por rango. Además, puedes repetir el dado de localización de impacto.",
  "The difficulty of skill tests to hack computers is decreased by 1, to a minimum of 0.": "La dificultad de las pruebas de habilidad para piratear ordenadores se reduce en 1, hasta un mínimo de 0.",
  "When you heal a patient's HP using the First Aid action, increase the amount of HP healed by +1 per rank in this perk.": "Cuando curas PV a un paciente con la acción Primeros auxilios, los PV curados aumentan en +1 por rango de esta ventaja.",
  "When you make a thrown weapon attack, you may spend 1 AP to increase the Range of the weapon by one step - from Close to Medium, or from Medium to Long.": "Cuando haces un ataque con un arma arrojadiza, puedes gastar 1 PA para aumentar un paso el alcance del arma: de corto a medio, o de medio a largo.",
  "When you make an attack against an NPC with one of the Mammal, Lizard, or Insect keywords and the Mutated keyword, your attack gains the Vicious damage effect, if it did not already have that effect.": "Cuando atacas a un PNJ que tenga una de las palabras clave Mamífero, Lagarto o Insecto y además la palabra clave Mutado, tu ataque gana el efecto de daño Despiadado, si no lo tenía ya.",
  "When you attempt a Lockpick skill test to unlock a door or container, you may re-roll 1d20.": "Cuando haces una prueba de Forzar cerraduras para abrir una puerta o un contenedor, puedes repetir 1d20.",
  "Because you lead by example, the maximum number of AP the group may save is increased by 1.": "Como predicas con el ejemplo, el número máximo de PA que puede guardar el grupo aumenta en 1.",
  "Increase any one S.P.E.C.I.A.L attribute by 1 rank. As usual, your S.P.E.C.I.A.L attributes cannot be increased beyond 10 using this method.": "Aumenta en 1 rango cualquier atributo de S.P.E.C.I.A.L. Como siempre, tus atributos de S.P.E.C.I.A.L. no pueden pasar de 10 de esta forma.",
  "Intense Training": "Entrenamiento intensivo",
  "At rank 1, your unarmed attacks inflict +1 CD damage. At rank 2, your unarmed attacks also gain the Vicious damage effect.": "En el rango 1, tus ataques sin armas infligen +1 DC de daño. En el rango 2, tus ataques sin armas ganan además el efecto de daño Despiadado.",
  "The difficulty of any CHA + Barter test you attempt to buy or sell goods is reduced by 1, to a minimum of 0.": "La dificultad de cualquier prueba de CAR + Trueque para comprar o vender mercancías se reduce en 1, hasta un mínimo de 0.",
  "You can repair an item without needing to expend any components. However, the repair is temporary, and the item will break again on the next complication you suffer while using it. The complication range of all skill tests to use the item increases by 1, to the roll of a 19–20.": "Puedes reparar un objeto sin gastar componentes. Sin embargo, la reparación es temporal, y el objeto volverá a romperse con la próxima complicación que sufras al usarlo. El rango de complicación de todas las pruebas de habilidad para usar el objeto aumenta en 1, a un resultado de 19-20.",
  "When you make an attack with a ranged energy weapon, the damage is increased by +1DDCD per rank in this perk.": "Cuando atacas con un arma de energía a distancia, el daño aumenta en +1 DC por rango de esta ventaja.",
  "Laser Commander": "Comandante láser",
  "At rank 1, you may re-roll the CD to determine if you suffer radiation damage from irradiated food or drink. At rank 2, you are immune to radiation damage from consuming irradiated food or drink.": "En el rango 1, puedes repetir el DC para saber si sufres daño por radiación al tomar comida o bebida irradiada. En el rango 2, eres inmune al daño por radiación de la comida y la bebida irradiadas.",
  "Increase your maximum health points by your Endurance rank.": "Tus puntos de vida máximos aumentan en tu rango de Resistencia.",
  "Life Giver": "Dador de vida",
  "When you roll to generate any complications on an Agility-based skill test, you may ignore one complication for every 1 AP spent. In addition, you may re-roll 1d20 on any AGI + Athletics test to avoid traps triggered by pressure plates or similar mechanisms.": "Cuando tiras para ver si hay complicaciones en una prueba de habilidad basada en Agilidad, puedes ignorar una complicación por cada 1 PA que gastes. Además, puedes repetir 1d20 en cualquier prueba de AGI + Atletismo para evitar trampas activadas por placas de presión o mecanismos parecidos.",
  "When you are attempting to pick a lock or pickpocket somebody, the difficulty of the opponent's skill test to detect you increases by +1.": "Cuando intentas forzar una cerradura o robarle a alguien, la dificultad de la prueba de habilidad del oponente para detectarte aumenta en +1.",
  "When you use the First Aid action to try to treat an injury, you can re-roll 1d20.": "Cuando usas la acción Primeros auxilios para tratar una herida, puedes repetir 1d20.",
  "When you kill an enemy with an energy weapon, they explode. Roll a number of CD equal to half the weapon's damage rating (round down). For each Effect rolled, one creature within Close range of the exploding enemy (starting with the closest) suffers energy damage equal to the total rolled on the CD.": "Cuando matas a un enemigo con un arma de energía, explota. Tira tantos DC como la mitad del valor de daño del arma (redondeando hacia abajo). Por cada Efecto, una criatura a corto alcance del enemigo que explota (empezando por la más cercana) sufre un daño de energía igual al total de la tirada de DC.",
  "When you make a sneak attack with a silenced or suppressed weapon, the damage is increased by +2 CD. You cannot gain this benefit while in Power Armor.": "Cuando haces un ataque furtivo con un arma silenciada o con supresor, el daño aumenta en +2 DC. No obtienes este beneficio si llevas servoarmadura.",
  "When you take the Sprint action, your Defense increases by +1 until the start of your next turn.": "Cuando haces la acción Correr, tu Defensa aumenta en +1 hasta el comienzo de tu siguiente turno.",
  "From time to time, a Mysterious Stranger comes to your aid, with lethal results. At the start of a combat encounter, you may spend 1 Luck point. If you do so, then at any point during the scene, the GM may have the Mysterious Stranger appear, make a single ranged attack against an enemy you attacked, or who just attacked you, and then vanish. If you spend a Luck point and the Mysterious Stranger does not appear, the GM must refund the Luck point you spent.": "De vez en cuando, un Desconocido misterioso acude en tu ayuda, con resultados letales. Al comienzo de un combate puedes gastar 1 punto de Suerte. Si lo haces, en cualquier momento de la escena el DJ puede hacer que aparezca el Desconocido misterioso, haga un único ataque a distancia contra un enemigo al que hayas atacado o que te acabe de atacar, y desaparezca. Si gastas el punto de Suerte y el Desconocido no aparece, el DJ debe devolvértelo.",
  "The stranger has an AGI of 10, a Small Guns skill of 6, and counts Small Guns as a Tag skill. They always roll 3d20 for attacks, rather than 2d20, and their attack - using a custom .44 Magnum revolver - inflicts 8 CD Piercing 1, Vicious physical damage. They always appear within their weapon's ideal range. Any attempt to find where the Stranger went after their attack fails.": "El desconocido tiene AGI 10, Armas ligeras 6 y Armas ligeras como habilidad marcada. Siempre tira 3d20 para atacar en lugar de 2d20, y su ataque, con un revólver Magnum del .44 personalizado, inflige 8 DC de daño físico Perforante 1, Despiadado. Siempre aparece al alcance ideal de su arma. Cualquier intento de averiguar adónde ha ido tras su ataque fracasa.",
  "While your health is reduced to less than ¼ of your maximum, you add +1 to your physical DR, +1 to your energy DR, and +1 CD to the damage of all your attacks.": "Mientras tu salud esté por debajo de ¼ de tu máximo, sumas +1 a tu RD física, +1 a tu RD de energía y +1 DC al daño de todos tus ataques.",
  "At rank 2, this increases to +2 DR, and +2 CD damage. At rank 3, this increases to +3 DR and +3 CD damage.": "En el rango 2, pasa a +2 RD y +2 DC de daño. En el rango 3, pasa a +3 RD y +3 DC de daño.",
  "Nerd Rage!": "¡Furia friki!",
  "You reduce any difficulty increases due to darkness by 1.": "Reduces en 1 cualquier aumento de dificultad causado por la oscuridad.",
  "When you make a sneak attack with a melee weapon or unarmed attack, the damage is increased by +2 CD. You cannot gain this benefit while in Power Armor.": "Cuando haces un ataque furtivo con un arma cuerpo a cuerpo o sin armas, el daño aumenta en +2 DC. No obtienes este beneficio si llevas servoarmadura.",
  "Whenever you use a weapon that inflicts radiation damage, or has the Radioactive damage effect, each Effect you roll inflicts one additional point of radiation damage.": "Cada vez que usas un arma que inflige daño por radiación o tiene el efecto de daño Radiactivo, cada Efecto que saques inflige un punto adicional de daño por radiación.",
  "In addition, fusion cores you use have 3 additional charges.": "Además, los núcleos de fusión que usas tienen 3 cargas adicionales.",
  "You may Charge as a major action if you are wearing Power Armor or are a super mutant. This is a movement action, and you may not Move or Sprint in the same turn. When you take this action, you move into reach of an enemy within Medium range (1 zone) and make a STR + Athletics test with a difficulty of 2. If you succeed, the enemy suffers damage equal to your normal unarmed damage, and is knocked prone.": "Puedes Embestir como acción principal si llevas servoarmadura o eres un supermutante. Es una acción de movimiento, y no puedes Moverte ni Correr en el mismo turno. Al hacerla, te mueves hasta el alcance de un enemigo a alcance medio (1 zona) y haces una prueba de FUE + Atletismo con dificultad 2. Si tienes éxito, el enemigo sufre un daño igual a tu daño normal sin armas y queda derribado.",
  "At rank 2, you add +1 CD and the Stun damage effect to the damage inflicted. At the GM's discretion, especially large or sturdy creatures cannot be knocked prone by this action.": "En el rango 2, sumas +1 DC y el efecto de daño Aturdidor al daño infligido. A criterio del DJ, las criaturas especialmente grandes o robustas no pueden ser derribadas con esta acción.",
  "When you make an unarmed attack, and choose to strike a specific location, your attack gains the Stun damage effect.": "Cuando haces un ataque sin armas y eliges golpear una localización concreta, tu ataque gana el efecto de daño Aturdidor.",
  "You cannot become addicted to alcoholic drinks, and whenever you drink an alcoholic drink, you heal +2 HP.": "No puedes volverte adicto a las bebidas alcohólicas, y cada vez que tomas una bebida alcohólica, te curas +2 PV.",
  "Party Boy / Party Girl": "Fiestero / Fiestera",
  "When travelling over long distances through the wilderness, a successful PER + Survival test (with a difficulty determined by the GM, based on the terrain) reduces the travel time by half.": "Al viajar largas distancias por territorio salvaje, una prueba de PER + Supervivencia superada (con la dificultad que fije el DJ según el terreno) reduce el tiempo de viaje a la mitad.",
  "When you are scavenging a location that contains medicine or chems, you find one additional item, randomly determined, without spending AP.": "Cuando rebuscas en un lugar que contiene medicinas o drogas, encuentras un objeto adicional, determinado al azar, sin gastar PA.",
  "At rank 1, you can ignore the first complication you roll when you make an AGI + Sneak test to steal an object from someone else's person or to plant something on them.": "En el rango 1, puedes ignorar la primera complicación que saques al hacer una prueba de AGI + Sigilo para robar un objeto que alguien lleva encima o para colocarle algo.",
  "At rank 2, you can re-roll 1d20 in your dice pool when attempting to pick someone's pocket.": "En el rango 2, puedes repetir 1d20 de tu reserva de dados al intentar robarle a alguien.",
  "At rank 3, you reduce the difficulty of attempts to pick someone's pocket by 1.": "En el rango 3, reduces en 1 la dificultad de los intentos de robarle a alguien.",
  "Your attacks using unarmed attacks and bladed melee weapons gain the Piercing 1 damage effect, or add +1 to the rating of any Piercing X damage effect they already had.": "Tus ataques sin armas y con armas cuerpo a cuerpo con filo ganan el efecto de daño Perforante 1, o suman +1 al valor de cualquier efecto Perforante X que ya tuvieran.",
  "The damage you deal using fire-based weapons increases by +1 CD per rank.": "El daño que haces con armas incendiarias aumenta en +1 DC por rango.",
  "Pyromaniac": "Pirómano",
  "Each turn, you may draw a single weapon or item carried on your person without using a minor action.": "Cada turno, puedes desenfundar un arma u objeto que lleves encima sin usar una acción secundaria.",
  "You can reload firearms faster. When you make a ranged attack, you may spend 2 AP to increase the Fire Rate of your gun by +2 for that attack.": "Recargas las armas de fuego más rápido. Cuando haces un ataque a distancia, puedes gastar 2 PA para aumentar en +2 la Cadencia de tu arma en ese ataque.",
  "Your radiation Damage Resistance, to all hit locations, increases by +1 per rank in this perk.": "Tu resistencia al daño por radiación, en todas las localizaciones, aumenta en +1 por cada rango de esta ventaja.",
  "Your energy Damage Resistance to all hit locations increases by +1 per rank in this perk.": "Tu resistencia al daño de energía en todas las localizaciones aumenta en +1 por cada rango de esta ventaja.",
  "If an enemy makes a ranged attack against you and rolls a complication, you may spend one Luck point to have their ricochet hit them. Resolve the damage roll against the attacking enemy instead.": "Si un enemigo te hace un ataque a distancia y saca una complicación, puedes gastar un punto de Suerte para que el rebote le alcance a él. Resuelve la tirada de daño contra el enemigo atacante.",
  "Ricochet": "Rebote",
  "When you make a ranged attack with any two-handed weapon with a Fire Rate of 2 or lower (except heavy weapons), you add +1 CD to the weapon's damage per rank.": "Cuando haces un ataque a distancia con cualquier arma a dos manos de Cadencia 2 o menos (salvo armas pesadas), sumas +1 DC al daño del arma por rango.",
  "At rank 2, you also add the Piercing 1 damage effect, or add +1 to the rating of any Piercing X damage effect the weapon already had.": "En el rango 2, además añades el efecto de daño Perforante 1, o sumas +1 al valor de cualquier efecto Perforante X que ya tuviera el arma.",
  "Rifleman": "Fusilero",
  "At rank 1, you can modify robot armor, weapon mounts, and modules with rank 1 mods. At rank 2 you gain access to rank 2 mods, and the difficulty of tests to repair robots is permanently reduced by 1. At rank 3 you gain access to rank 3 mods, and you can reprogram robots to fulfil a different function or alter their behavior at the discretion of the GM.": "En el rango 1, puedes modificar armaduras de robot, soportes de armas y módulos con mods de rango 1. En el rango 2 accedes a los mods de rango 2, y la dificultad de las pruebas para reparar robots se reduce en 1 de forma permanente. En el rango 3 accedes a los mods de rango 3, y puedes reprogramar robots para que cumplan otra función o cambien su comportamiento, a criterio del DJ.",
  "You can modify energy weapons with weapon mods, and you can also craft certain advanced armor mods. Each rank in this perk unlocks an additional rank of mods: rank 1 unlocks rank 1 mods, rank 2 unlocks rank 2 mods, etc.": "Puedes modificar armas de energía con mods de arma, y también fabricar ciertos mods de armadura avanzados. Cada rango de esta ventaja desbloquea un rango más de mods: el rango 1 desbloquea los mods de rango 1, el rango 2 los de rango 2, etc.",
  "When you make a CHA + Speech test to convince someone of a lie, you may ignore the first complication you roll.": "Cuando haces una prueba de CAR + Conversación para convencer a alguien de una mentira, puedes ignorar la primera complicación que saques.",
  "When you scrap an item, you can salvage uncommon component materials as well as common ones (see p.208). At rank 2, you can also salvage rare materials.": "Cuando desguazas un objeto, puedes recuperar materiales poco comunes además de los comunes (ver p. 208). En el rango 2, también puedes recuperar materiales raros.",
  "Scrapper": "Chatarrero",
  "Whenever you roll to determine how much ammunition you find, you find more.": "Cada vez que tiras para saber cuánta munición encuentras, encuentras más.",
  "At rank 1, you find +3 CD additional shots. At rank 2, you find +6 CD additional shots. At rank 3, you find +10 CD additional shots. The additional ammo you find is the same as initially found, for example, if you find 10mm ammunition, this perk increases how much 10mm ammo you find. If you find multiple types of ammunition, Scrounger applies to the ammunition with the lowest rarity (GM's choice if there is a tie).": "En el rango 1, encuentras +3 DC disparos adicionales. En el rango 2, +6 DC disparos adicionales. En el rango 3, +10 DC disparos adicionales. La munición extra es del mismo tipo que la encontrada: por ejemplo, si encuentras munición de 10 mm, esta ventaja aumenta la munición de 10 mm que encuentras. Si encuentras varios tipos, Gorrón se aplica a la munición de menor rareza (si hay empate, elige el DJ).",
  "Your ranged attacks using shotguns gain the Piercing 1 damage effect, or add +1 to any Piercing X damage effect the weapon already had.": "Tus ataques a distancia con escopetas ganan el efecto de daño Perforante 1, o suman +1 a cualquier efecto Perforante X que ya tuviera el arma.",
  "When you make a ranged attack with any heavy weapon, you add +1 CD to the weapon's damage, per rank.": "Cuando haces un ataque a distancia con cualquier arma pesada, sumas +1 DC al daño del arma por rango.",
  "Add +1 rank to two skills or add +2 ranks to one skill. No skill may have more than 6 ranks.": "Suma +1 rango a dos habilidades o +2 rangos a una habilidad. Ninguna habilidad puede tener más de 6 rangos.",
  "Skilled": "Habilidoso",
  "When you inflict any damage with an unarmed attack or melee weapon, you may spend 1 Luck point to immediately inflict a critical hit - and therefore an injury - on the location hit.": "Cuando haces cualquier daño con un ataque sin armas o un arma cuerpo a cuerpo, puedes gastar 1 punto de Suerte para infligir de inmediato un golpe crítico, y por tanto una herida, en la localización alcanzada.",
  "When you make a Barter or Speech test as part of an opposed test, you may re-roll 1d20.": "Cuando haces una prueba de Trueque o Conversación como parte de una prueba enfrentada, puedes repetir 1d20.",
  "Your poison Damage Resistance increases by +2.": "Tu resistencia al daño por veneno aumenta en +2.",
  "When you take the Aim minor action, and then make a ranged attack with a two-handed weapon with the Accurate quality, you can specify a hit location to target without increasing the difficulty of the attack.": "Cuando haces la acción secundaria Apuntar y luego un ataque a distancia con un arma a dos manos con la cualidad Precisa, puedes elegir la localización de impacto sin aumentar la dificultad del ataque.",
  "For every hour you spend in direct sunlight, you heal 1 radiation damage.": "Por cada hora que pasas bajo la luz directa del sol, te curas 1 de daño por radiación.",
  "When you take the Aim minor action, you may either re-roll 2d20 on the first attack you make this turn, or re-roll 1d20 on all attacks you make this turn.": "Cuando haces la acción secundaria Apuntar, puedes repetir 2d20 en el primer ataque que hagas este turno, o repetir 1d20 en todos los ataques que hagas este turno.",
  "Your maximum carry weight is increased by +25 lbs., per rank.": "Tu capacidad de carga máxima aumenta en +25 lb por rango.",
  "You may select one additional Tag skill. Increase the skill's rank by 2, to a maximum of 6, and mark it as a Tag skill, allowing you to roll a critical success with a d20 result equal or under the skill's rank.": "Puedes elegir una habilidad marcada más. Aumenta el rango de esa habilidad en 2, hasta un máximo de 6, y márcala como habilidad marcada, lo que te permite sacar un éxito crítico con un resultado del d20 igual o menor que el rango de la habilidad.",
  "Tag!": "¡Marcada!",
  "When you make a Speech test to threaten or scare someone, you may re-roll 1d20.": "Cuando haces una prueba de Conversación para amenazar o asustar a alguien, puedes repetir 1d20.",
  "At rank 2, you may use a major action in combat to threaten an enemy within Medium range, using a STR + Speech test with a difficulty of 2. If you succeed, that enemy must move away from you during their next turn (though they can take any other actions they wish).": "En el rango 2, puedes usar una acción principal en combate para amenazar a un enemigo a alcance medio, con una prueba de FUE + Conversación de dificultad 2. Si tienes éxito, ese enemigo debe alejarse de ti en su siguiente turno (aunque puede hacer cualquier otra acción que quiera).",
  "Terrifying Presence": "Presencia aterradora",
  "Your physical Damage Resistance to all hit locations increases by +1 per rank in this perk.": "Tu resistencia al daño físico en todas las localizaciones aumenta en +1 por rango de esta ventaja.",
});

// ---- v4.27.0: perk arrows, maps
Object.assign(ES, {
  "Previous perk": "Ventaja anterior",
  "Next perk": "Ventaja siguiente",
  "Maps": "Mapas",
  "Quest maps in Pip-Boy style": "Mapas de misiones al estilo Pip-Boy",
  "Pick a quest to open its map. Tap a location to see its local map, and any mark to see who or what is there.": "Elige una misión para abrir su mapa. Toca un lugar para ver su mapa local, y cualquier marca para ver quién o qué hay ahí.",
});

